# Hypothesis 2: Swap colors 4 and 5, keep 6
def swap_colors(grid):
    result = []
    for row in grid:
        new_row = []
        for v in row:
            if v == 4:
                new_row.append(5)
            elif v == 5:
                new_row.append(4)
            else:
                new_row.append(v)
        result.append(new_row)
    return result

